//! The table-driven encodings of `Encode` (`Encode::XS` objects): a port of
//! `encengine.c` (`do_encode`) and `Encode.xs` (`encode_method`), walking the
//! tables enc2xs compiled from Encode 3.21's `.ucm` files
//! (`data/encode_tables.bin`, generated by
//! `tools/oracle/probes/perl-compat/gen_encode_tables.pl`).

use std::sync::OnceLock;

static BLOB: &[u8] = include_bytes!("../../data/encode_tables.bin");

#[derive(Clone, Copy)]
struct Entry {
    min: u8,
    max: u8,
    dlen: u8,
    slen: u8,
    next: u32,
    seq: u32,
}

/// One table-driven encoding.
pub(crate) struct XsEnc {
    pub name: String,
    pub rep: Vec<u8>,
    /// Decoding direction (`t_utf8`: bytes → UTF-8).
    t_utf8: u32,
    /// Encoding direction (`f_utf8`: UTF-8 → bytes).
    f_utf8: u32,
}

struct Tables {
    bytes: &'static [u8],
    /// Per page: (first entry index, entry count).
    pages: Vec<(u32, u16)>,
    entries: Vec<Entry>,
    encs: Vec<XsEnc>,
}

fn tables() -> &'static Tables {
    static T: OnceLock<Tables> = OnceLock::new();
    T.get_or_init(|| {
        let b = BLOB;
        let mut p = 0usize;
        let mut take = |n: usize| {
            let s = &b[p..p + n];
            p += n;
            s
        };
        assert_eq!(take(4), b"PCEN", "encode_tables.bin magic");
        let u32le = |s: &[u8]| u32::from_le_bytes([s[0], s[1], s[2], s[3]]);
        assert_eq!(u32le(take(4)), 1, "encode_tables.bin version");
        let nbytes = u32le(take(4)) as usize;
        let bytes = take(nbytes);
        let npages = u32le(take(4)) as usize;
        let mut pages = Vec::with_capacity(npages);
        let mut entries = Vec::new();
        for _ in 0..npages {
            let s = take(2);
            let n = u16::from_le_bytes([s[0], s[1]]);
            pages.push((entries.len() as u32, n));
            for _ in 0..n {
                let e = take(12);
                entries.push(Entry {
                    min: e[0],
                    max: e[1],
                    dlen: e[2],
                    slen: e[3],
                    next: u32le(&e[4..8]),
                    seq: u32le(&e[8..12]),
                });
            }
        }
        let nenc = u32le(take(4)) as usize;
        let mut encs = Vec::with_capacity(nenc);
        for _ in 0..nenc {
            let l = take(1)[0] as usize;
            let name = String::from_utf8(take(l).to_vec()).expect("name");
            let l = take(1)[0] as usize;
            let rep = take(l).to_vec();
            let _minmax = take(2);
            let t_utf8 = u32le(take(4));
            let f_utf8 = u32le(take(4));
            encs.push(XsEnc {
                name,
                rep,
                t_utf8,
                f_utf8,
            });
        }
        assert_eq!(p, b.len(), "encode_tables.bin trailing data");
        Tables {
            bytes,
            pages,
            entries,
            encs,
        }
    })
}

/// The table-driven encoding with this canonical name.
pub(crate) fn find(name: &str) -> Option<&'static XsEnc> {
    tables().encs.iter().find(|e| e.name == name)
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub(crate) enum Code {
    Done,
    Partial,
    NoRep,
    Fallback,
}

/// `do_encode` (encengine.c): walk `src` from page `page`, appending output.
/// Returns the code and the length of `src` consumed up to the last complete
/// sequence (`last - src`).
fn do_encode(t: &Tables, page: u32, src: &[u8], out: &mut Vec<u8>, approx: bool) -> (Code, usize) {
    let mut s = 0usize;
    let mut last = 0usize;
    let mut code = Code::Done;
    let mut page = page;
    while s < src.len() {
        let byte = src[s];
        let (first, n) = t.pages[page as usize];
        let ents = &t.entries[first as usize..first as usize + n as usize];
        // while (byte > e->max) e++;
        let e = ents[ents.partition_point(|e| e.max < byte)];
        if byte >= e.min && e.slen != 0 && (approx || e.slen & 0x80 == 0) {
            let cend = s + (e.slen & 0x7f) as usize;
            if cend <= src.len() {
                let n = e.dlen as usize;
                if n > 0 {
                    let off = e.seq as usize + n * (byte - e.min) as usize;
                    out.extend_from_slice(&t.bytes[off..off + n]);
                }
                page = e.next;
                s += 1;
                if s == cend {
                    if approx && e.slen & 0x80 != 0 {
                        code = Code::Fallback;
                    }
                    last = s;
                }
            } else {
                code = Code::Partial;
                break;
            }
        } else {
            code = Code::NoRep;
            break;
        }
    }
    (code, last)
}

/// `utf8n_to_uvchr(s, len, UTF8_ALLOW_ANY)` on a valid UTF-8 stream cut at
/// arbitrary byte positions: the code point (U+FFFD if malformed) and the
/// number of bytes it takes.
pub(crate) fn utf8_any(s: &[u8]) -> (u32, usize) {
    let b = s[0];
    let need = match b {
        0x00..=0x7F => return (b as u32, 1),
        0xC0..=0xDF => 2,
        0xE0..=0xEF => 3,
        0xF0..=0xF7 => 4,
        _ => return (0xFFFD, 1),
    };
    let avail = s[1..]
        .iter()
        .take(need - 1)
        .take_while(|c| (0x80..=0xBF).contains(*c))
        .count();
    if avail < need - 1 {
        return (0xFFFD, 1 + avail);
    }
    let mut v = (b as u32) & (0x7F >> need);
    for c in &s[1..need] {
        v = (v << 6) | (*c as u32 & 0x3F);
    }
    (v, need)
}

/// The CHECK argument of an `encode`/`decode` call.
#[derive(Clone, Copy)]
pub(crate) struct Check<'a> {
    /// `DIE_ON_ERR` (`FB_CROAK`).
    pub die: bool,
    /// `PERLQQ` (or a code reference).
    pub perlqq: bool,
    /// The CHECK is non-zero (zero means "approximate": fallback mappings and
    /// the replacement character are used).
    pub nonzero: bool,
    /// A code-reference CHECK (`sub { ... }`), called with the code point.
    pub cb: Option<&'a dyn Fn(u32) -> Vec<u8>>,
}

impl Check<'_> {
    /// `$PerlIO::encoding::fallback` as the `:encoding` layer passes it:
    /// `PERLQQ|WARN_ON_ERR|ONLY_PRAGMA_WARNINGS|STOP_AT_PARTIAL`.
    pub const PERLIO: Check<'static> = Check {
        die: false,
        perlqq: true,
        nonzero: true,
        cb: None,
    };
    /// `FB_PERLQQ`.
    pub const FB_PERLQQ: Check<'static> = Check::PERLIO;
    /// `FB_CROAK|STOP_AT_PARTIAL` (File::Slurper's read layer).
    pub const CROAK: Check<'static> = Check {
        die: true,
        perlqq: false,
        nonzero: true,
        cb: None,
    };
    /// `FB_DEFAULT` (0).
    pub const DEFAULT: Check<'static> = Check {
        die: false,
        perlqq: false,
        nonzero: false,
        cb: None,
    };
}

/// Direction of a conversion.
#[derive(Clone, Copy, PartialEq, Eq)]
pub(crate) enum Dir {
    Encode,
    Decode,
}

/// `encode_method` (Encode.xs:147): convert `src`, returning the output and
/// the offset of the first unconsumed byte (`Encode` writes `src[rest..]`
/// back into the source when CHECK is non-zero without `LEAVE_SRC`).
pub(crate) fn encode_method(
    enc: &XsEnc,
    dir: Dir,
    src: &[u8],
    chk: Check<'_>,
) -> Result<(Vec<u8>, usize), String> {
    let t = tables();
    let page = match dir {
        Dir::Encode => enc.f_utf8,
        Dir::Decode => enc.t_utf8,
    };
    let mut out = Vec::with_capacity(src.len() + 1);
    let mut pos = 0usize;
    loop {
        let (code, slen) = do_encode(t, page, &src[pos..], &mut out, !chk.nonzero);
        match code {
            Code::Done | Code::Fallback | Code::Partial => {
                pos += slen;
                break;
            }
            Code::NoRep => {
                let p = pos + slen;
                if dir == Dir::Encode {
                    let (ch, clen) = utf8_any(&src[p..]);
                    if chk.die {
                        return Err(format!("\"\\x{{{ch:04x}}}\" does not map to {}", enc.name));
                    }
                    if chk.perlqq {
                        match chk.cb {
                            Some(cb) => out.extend(cb(ch)),
                            None => out.extend(format!("\\x{{{ch:04x}}}").bytes()),
                        }
                    } else {
                        out.extend_from_slice(&enc.rep);
                    }
                    pos = p + clen;
                } else {
                    let b = src[p];
                    if chk.die {
                        return Err(format!(
                            "{} \"\\x{b:02X}\" does not map to Unicode",
                            enc.name
                        ));
                    }
                    if chk.perlqq {
                        out.extend(format!("\\x{b:02X}").bytes());
                    } else {
                        out.extend_from_slice("\u{FFFD}".as_bytes());
                    }
                    pos = p + 1;
                }
            }
        }
    }
    Ok((out, pos))
}

#[cfg(test)]
mod tests {
    use super::*;

    fn enc(name: &str, s: &str) -> Vec<u8> {
        encode_method(
            find(name).unwrap(),
            Dir::Encode,
            s.as_bytes(),
            Check::PERLIO,
        )
        .unwrap()
        .0
    }

    #[test]
    fn basics() {
        assert!(tables().encs.len() > 100);
        assert_eq!(enc("iso-8859-1", "aé€"), b"a\xe9\\x{20ac}");
        assert_eq!(enc("shiftjis", "あ"), b"\x82\xa0");
        assert_eq!(enc("euc-jp", "\u{4E02}\u{FF71}"), b"\x8f\xb0\xa1\x8e\xb1");
        let (d, _) = encode_method(
            find("cp932").unwrap(),
            Dir::Decode,
            b"\x82\xa0",
            Check::CROAK,
        )
        .unwrap();
        assert_eq!(d, "あ".as_bytes());
        let e = encode_method(find("cp1252").unwrap(), Dir::Decode, b"\x81", Check::CROAK);
        assert_eq!(e.unwrap_err(), "cp1252 \"\\x81\" does not map to Unicode");
    }
}
